-- Widget toolkit. Every piece of chrome is drawn from the addon's own textures
-- in Media/ (generated by tools/make_art.py): 9-sliced panels and buttons,
-- slots with quality frames, round portraits, pills and badges. Game icons are
-- only used for things that exist in the game (items, spells, classes).
local ADDON, ns = ...

local floor, max, min = math.floor, math.max, math.min

local UI = {}
ns.UI = UI

UI.MEDIA = "Interface\\AddOns\\" .. (ADDON or "BigIdleHeroes") .. "\\Media\\"

function UI.Tex(name)
	return UI.MEDIA .. name .. ".tga"
end

-- Palette
UI.C = {
	gold  = { 0.62, 0.80, 1.00 },
	coin  = { 1.00, 0.82, 0.29 },
	text  = { 0.92, 0.94, 0.98 },
	sub   = { 0.62, 0.68, 0.80 },
	dim   = { 0.42, 0.46, 0.56 },
	red   = { 1.00, 0.36, 0.32 },
	green = { 0.40, 0.92, 0.50 },
	blue  = { 0.48, 0.72, 1.00 },
}
UI.STYLE = {
	primary = { 0.20, 0.52, 1.00 },
	blue    = { 0.34, 0.43, 0.62 },
	green   = { 0.22, 0.66, 0.34 },
	red     = { 0.80, 0.25, 0.23 },
	dark    = { 0.20, 0.27, 0.40 },
	purple  = { 0.55, 0.36, 0.86 },
	off     = { 0.20, 0.22, 0.27 },
}
-- the faction picker's Alliance button: the Alliance's own blue (ns.FACTIONS)
UI.STYLE.alliance = { ns.U.rgb("4a8cff") }

------------------------------------------------------------------------
-- Textures and text
------------------------------------------------------------------------
function UI.Fill(tex, r, g, b, a)
	if tex.SetColorTexture then
		tex:SetColorTexture(r, g, b, a or 1)
	else
		tex:SetTexture(r, g, b, a or 1) -- clients older than 7.0
	end
end

local ICON_PATH = "Interface\\Icons\\"

function UI.SetIcon(tex, name)
	tex:SetTexture(ICON_PATH .. (name or "INV_Misc_QuestionMark"))
	tex:SetTexCoord(0.08, 0.92, 0.08, 0.92)
end

function UI.SetClassIcon(tex, classId)
	local art = classId and UI.ArtIcon("icon_" .. classId:lower())
	if art then
		tex:SetTexture(art)
		tex:SetTexCoord(0, 1, 0, 1)
		return
	end
	local c = ns.CLASS_ICON_COORD[classId]
	tex:SetTexture(ns.CLASS_ICON_FILE)
	if c then tex:SetTexCoord(c[1], c[2], c[3], c[4]) end
end

-- Imported art (Data/Art.lua): path of an icon, or nil.
function UI.ArtIcon(id)
	local icons = ns.ART and ns.ART.icons
	local e = icons and icons[id]
	return e and (UI.MEDIA .. "Art\\" .. e.file) or nil
end

-- An icon from the imported art if there is one, else a game icon.
-- (tex.isArt: the add-on's own white icon, drawn in a tint)
function UI.SetArtOrIcon(tex, artId, iconName)
	local art = artId and UI.ArtIcon(artId)
	if art then
		tex:SetTexture(art)
		tex:SetTexCoord(0, 1, 0, 1)
		tex.isArt = true
	else
		UI.SetIcon(tex, iconName)
		tex.isArt = nil
		tex:SetVertexColor(1, 1, 1)
	end
end

-- A rounded line of the scroll bar sheet in three pieces (a round cap at
-- each end and the middle), so its ends stay round at any length.
-- line:Place(rel, relPoint, vertical, x, y, len, thick, squareA, squareB):
-- from (x, y) off rel's relPoint (a vertical line's top middle, a horizontal
-- one's left middle), len long, thick wide; squareA / squareB: that end
-- (top or left / bottom or right) cut square, to meet a bend (UI.Bend).
-- line:SetColor(r, g, b, a), line:SetShown(v).
local LINE_CAP = 0.017 -- the share of the bar picture's length one round end takes
-- the scroll bar sheet's two bars: its dark one and its blue one
UI.BAR_DARK = { 0.27, 0.33, 0.39 }
UI.BAR_BLUE = { 0.46, 0.62, 0.76 }
function UI.Line3(parent, layer, sub)
	local o = { t = {}, shown = true }
	for i = 1, 3 do o.t[i] = parent:CreateTexture(nil, layer or "BORDER", nil, sub) end
	function o:Place(rel, relPoint, vertical, x, y, len, thick, squareA, squareB)
		local art = UI.ArtIcon(vertical and "sb_bar_v" or "sb_bar_h")
		self.art = art
		local cap = math.min(thick / 2, len / 2)
		local ca, cb = squareA and 0 or cap, squareB and 0 or cap
		local mid = math.max(0, len - ca - cb)
		self.mid, self.ca, self.cb = mid, ca, cb
		local a, m, b = self.t[1], self.t[2], self.t[3]
		for _, t in ipairs(self.t) do
			t:ClearAllPoints()
			if art then t:SetTexture(art) end
		end
		if vertical then
			a:SetSize(thick, math.max(1, ca))
			a:SetPoint("TOPLEFT", rel, relPoint, x - thick / 2, y)
			m:SetSize(thick, math.max(1, mid))
			m:SetPoint("TOPLEFT", rel, relPoint, x - thick / 2, y - ca)
			b:SetSize(thick, math.max(1, cb))
			b:SetPoint("TOPLEFT", rel, relPoint, x - thick / 2, y - ca - mid)
			if art then
				a:SetTexCoord(0, 1, 0, LINE_CAP)
				m:SetTexCoord(0, 1, LINE_CAP, 1 - LINE_CAP)
				b:SetTexCoord(0, 1, 1 - LINE_CAP, 1)
			end
		else
			a:SetSize(math.max(1, ca), thick)
			a:SetPoint("TOPLEFT", rel, relPoint, x, y + thick / 2)
			m:SetSize(math.max(1, mid), thick)
			m:SetPoint("TOPLEFT", rel, relPoint, x + ca, y + thick / 2)
			b:SetSize(math.max(1, cb), thick)
			b:SetPoint("TOPLEFT", rel, relPoint, x + ca + mid, y + thick / 2)
			if art then
				a:SetTexCoord(0, LINE_CAP, 0, 1)
				m:SetTexCoord(LINE_CAP, 1 - LINE_CAP, 0, 1)
				b:SetTexCoord(1 - LINE_CAP, 1, 0, 1)
			end
		end
		if self.rgba then self:SetColor(unpack(self.rgba)) end
		self:SetShown(self.shown)
	end
	function o:SetColor(r, g, b, a)
		self.rgba = { r, g, b, a or 1 }
		for _, t in ipairs(self.t) do
			if self.art then t:SetVertexColor(r, g, b, a or 1) else t:SetColorTexture(r, g, b, a or 1) end
		end
	end
	function o:SetShown(v)
		self.shown = v and true or false
		self.t[1]:SetShown(self.shown and (self.ca or 1) > 0)
		self.t[2]:SetShown(self.shown and (self.mid or 0) > 0)
		self.t[3]:SetShown(self.shown and (self.cb or 1) > 0)
	end
	function o:Show() self:SetShown(true) end
	function o:Hide() self:SetShown(false) end
	return o
end

-- Where a line of the scroll bar sheet turns: the bar bent a quarter round,
-- between two square-ended lines (UI.Line3). bend:Place(rel, relPoint, x, y,
-- thick, down): its middle at (x, y) off rel's relPoint; from the left, then
-- down (┐), or with up (┘) from above, then to the left. Same SetColor,
-- SetShown as a line.
function UI.Bend(parent, layer, sub)
	local o = { t = parent:CreateTexture(nil, layer or "BORDER", nil, sub), shown = true }
	function o:Place(rel, relPoint, x, y, thick, up)
		local art = UI.ArtIcon("sb_bend")
		self.art = art
		local t = self.t
		t:ClearAllPoints()
		t:SetSize(thick, thick)
		t:SetPoint("TOPLEFT", rel, relPoint, x - thick / 2, y + thick / 2)
		if art then
			t:SetTexture(art)
			if up then t:SetTexCoord(0, 1, 1, 0) else t:SetTexCoord(0, 1, 0, 1) end
		end
		if self.rgba then self:SetColor(unpack(self.rgba)) end
		self:SetShown(self.shown)
	end
	function o:SetColor(r, g, b, a)
		self.rgba = { r, g, b, a or 1 }
		if self.art then self.t:SetVertexColor(r, g, b, a or 1) else self.t:SetColorTexture(r, g, b, a or 1) end
	end
	function o:SetShown(v)
		self.shown = v and true or false
		self.t:SetShown(self.shown)
	end
	function o:Show() self:SetShown(true) end
	function o:Hide() self:SetShown(false) end
	return o
end

-- An arrow of the scroll bar sheet ("left", "right", "up", "down") on a
-- texture, in a colour. Returns false when the picture is missing.
function UI.SetArrow(tex, dir, r, g, b, a)
	local art = UI.ArtIcon("sb_arrow_" .. dir)
	if not art then return false end
	tex:SetTexture(art)
	tex:SetTexCoord(0, 1, 0, 1)
	tex:SetVertexColor(r or 1, g or 1, b or 1, a or 1)
	return true
end

-- A scroll bar's grip: silver, blue while in use (hot); its length goes
-- with how much of the list shows, within these bounds.
UI.GRIP_MIN, UI.GRIP_MAX = 24, 72
function UI.SetGrip(tex, hot)
	local art = UI.ArtIcon(hot and "sb_grip_v_hot" or "sb_grip_v")
	if art then
		tex:SetTexture(art)
		tex:SetTexCoord(0, 1, 0, 1)
		tex:SetVertexColor(1, 1, 1, 1)
	else
		UI.Fill(tex, 0.42, 0.70, 1, hot and 0.95 or 0.7)
	end
end

-- Hero face: the class circle.
function UI.SetHeroIcon(tex, heroId)
	local h = ns.db and ns.db.heroes[heroId]
	UI.SetClassIcon(tex, h and ns.SPECS[h.spec].class)
	return false
end

-- Path of an imported picture (an interface piece or an icon), or nil.
function UI.ArtPath(id)
	local a = ns.ART
	local e = id and a and ((a.ui and a.ui[id]) or (a.icons and a.icons[id]))
	return e and (UI.MEDIA .. "Art\\" .. e.file) or nil
end

-- Built-in glyphs that an imported picture replaces. tint = the picture is
-- drawn light so the game can colour it (rings, bars, slots); the others are
-- painted in their own colours and are never tinted.
UI.GLYPH_ART = {
	lock = { "icon_lock" }, check = { "icon_check" }, plus = { "icon_plus" }, close = { "icon_close" },
	arrow = { "icon_arrow" }, star = { "icon_star" }, crown = { "icon_crown" }, skull = { "icon_skull" },
	auto = { "icon_auto" },
	ring = { "ui_portrait_ring", tint = true }, bar = { "ui_bar_fill", tint = true }, slot = { "ui_slot", tint = true },
}

-- The role icons are the game's own (the group finder's): one texture, a
-- square per role (the client's GetTexCoordsForRole when it has it).
local ROLE_TEX = "Interface\\LFGFrame\\UI-LFG-ICON-ROLES"
local ROLE_KEY = { role_tank = "TANK", role_heal = "HEALER", role_dps = "DAMAGER" }
local ROLE_TC = {
	TANK = { 0, 67 / 256, 67 / 256, 134 / 256 },
	HEALER = { 67 / 256, 134 / 256, 0, 67 / 256 },
	DAMAGER = { 67 / 256, 134 / 256, 67 / 256, 134 / 256 },
}
function UI.RoleTexCoord(role)
	if type(GetTexCoordsForRole) == "function" then
		local ok, l, r, t, b = pcall(GetTexCoordsForRole, role)
		if ok and type(b) == "number" then return l, r, t, b end
	end
	local c = ROLE_TC[role] or ROLE_TC.DAMAGER
	return c[1], c[2], c[3], c[4]
end

-- Sets a glyph texture (imported picture if there is one), optionally tinted.
function UI.SetGlyph(t, name, r, g, b, a)
	if ROLE_KEY[name] then
		t:SetTexture(ROLE_TEX)
		t:SetTexCoord(UI.RoleTexCoord(ROLE_KEY[name]))
		t.painted = true
		t:SetVertexColor(1, 1, 1, a or 1)
		return
	end
	local m = UI.GLYPH_ART[name]
	local path = m and UI.ArtPath(m[1])
	if path then
		t:SetTexture(path)
		t:SetTexCoord(0, 1, 0, 1)
		t.painted = not m.tint
	else
		t:SetTexture(UI.Tex(name))
		t.painted = nil
	end
	if r then UI.Tint(t, r, g, b, a) end
end

-- Colours a glyph; painted pictures keep their own colours.
function UI.Tint(t, r, g, b, a)
	if t.painted then t:SetVertexColor(1, 1, 1, a or 1) else t:SetVertexColor(r, g, b, a or 1) end
end

-- A texture from Media/ (or the picture that replaces it), optionally tinted.
function UI.Art(parent, name, layer, r, g, b, a)
	local t = parent:CreateTexture(nil, layer or "ARTWORK")
	UI.SetGlyph(t, name, r, g, b, a)
	return t
end

function UI.Glyph(parent, name, size, r, g, b, layer)
	local t = UI.Art(parent, name, layer or "OVERLAY", r or 1, g or 1, b or 1)
	t:SetSize(size, size)
	return t
end

-- A loading screen (Data/LoadingScreens.lua) in a texture of the given shape
-- (width / height): a band across the middle of its picture, clear of the
-- frame, logo and dark bands around it. The game draws a texture that has no
-- size at the file's own size: each file is measured once that way, and a
-- picture stored in a taller texture (filled up below) is cut to its part.
local LOADSCREEN_KIND = {
	classic = { aspect = 4 / 3, mid = 0.50, top = 0.21, bottom = 0.79 },
	forever = { aspect = 16 / 9, mid = 0.49, top = 0.17, bottom = 0.82 },
}
local fileSize = {}                                   -- file -> { w, h }, false while measuring
local shownScreens = setmetatable({}, { __mode = "k" }) -- texture -> { screen, shape }
local probe

local function screenCoords(ls, shape)
	local k = LOADSCREEN_KIND[ls.kind] or LOADSCREEN_KIND.classic
	local h = k.aspect / shape -- share of the picture's height at its full width
	local l, r = 0, 1
	local room = k.bottom - k.top
	if h > room then -- taller than the picture's band: a narrower piece
		local w = room / h
		l, r, h = (1 - w) / 2, (1 + w) / 2, room
	end
	local t = math.max(k.top, math.min(k.bottom - h, k.mid - h / 2))
	local v = 1
	local size = fileSize[ls.file]
	if size and size[2] > 0 and size[1] / size[2] < k.aspect * 0.97 then v = (size[1] / size[2]) / k.aspect end
	return l, r, t * v, (t + h) * v
end

local function measure(file)
	if fileSize[file] ~= nil then return end
	fileSize[file] = false
	if not probe then
		probe = CreateFrame("Frame", nil, UIParent)
		probe:SetSize(1, 1)
		probe:SetPoint("TOPLEFT", UIParent, "TOPLEFT", 0, 0)
		probe.list = {}
		probe:SetScript("OnUpdate", function(self, elapsed)
			for f, t in pairs(self.list) do
				t.left = t.left - elapsed
				local w, h = t:GetWidth(), t:GetHeight()
				if w and h and w > 8 and h > 8 then
					fileSize[f] = { w, h }
				end
				if fileSize[f] or t.left <= 0 then
					t:Hide()
					self.list[f] = nil
					if fileSize[f] then
						for tex, d in pairs(shownScreens) do
							if d[1].file == f then tex:SetTexCoord(screenCoords(d[1], d[2])) end
						end
					end
				end
			end
			if not next(self.list) then self:Hide() end
		end)
	end
	local t = probe:CreateTexture(nil, "BACKGROUND")
	t:SetPoint("TOPLEFT", probe, "TOPLEFT", 0, 0) -- one point and no size: the file's own size
	t:SetTexture(file)
	t:SetAlpha(0)
	t.left = 5
	probe.list[file] = t
	probe:Show()
end

function UI.SetLoadingScreen(tex, ls, shape)
	if not ls then return false end
	-- a file the client cannot load: the original screen it stands in for,
	-- else nothing (the caller shows its own picture)
	if tex:SetTexture(ls.file) == false then
		ls = ls.fallback
		if not ls or tex:SetTexture(ls.file) == false then return false end
	end
	tex:SetTexCoord(screenCoords(ls, shape))
	tex:SetVertexColor(1, 1, 1)
	shownScreens[tex] = { ls, shape }
	measure(ls.file)
	return true
end

-- Sets a one-line text in the largest of `sizes` (big to small) that fits
-- `width`; the smallest when none does.
function UI.FitText(fs, text, width, sizes, flags)
	fs:SetText(text or "")
	for i, size in ipairs(sizes) do
		fs:SetFont(ns.FONT, size, flags or "")
		if fs:GetStringWidth() <= width or i == #sizes then break end
	end
end

function UI.Text(parent, size, text, flags, layer)
	local fs = parent:CreateFontString(nil, layer or "OVERLAY")
	local ok = fs:SetFont(ns.FONT, size or 12, flags or "")
	if ok == false then
		fs:SetFont(STANDARD_TEXT_FONT or "Fonts\\FRIZQT__.TTF", size or 12, flags or "")
	end
	fs:SetShadowColor(0, 0, 0, 0.9)
	fs:SetShadowOffset(1, -1)
	fs:SetJustifyH("LEFT")
	fs:SetTextColor(UI.C.text[1], UI.C.text[2], UI.C.text[3])
	if text then fs:SetText(text) end
	return fs
end

function UI.Color(fs, c)
	fs:SetTextColor(c[1], c[2], c[3])
end

------------------------------------------------------------------------
-- 9-slice
------------------------------------------------------------------------
-- texture size, edge in texels, default display edge in pixels
local ART = {
	panel  = { w = 64, h = 64, e = 18, d = 16 },
	card   = { w = 64, h = 64, e = 14, d = 11 },
	inset  = { w = 32, h = 32, e = 10, d = 8 },
	button = { w = 64, h = 32, e = 13, d = 10 },
	pill   = { w = 64, h = 32, e = 16, d = 0 },
	slot   = { w = 64, h = 64, e = 12, d = 8 },
	frame  = { w = 64, h = 64, e = 14, d = 9 },
	corners = { w = 64, h = 64, e = 14, d = 9 },
	fade_down = { w = 64, h = 64, e = 18, d = 11 },
	fade_up = { w = 64, h = 64, e = 18, d = 11 },
	shadow = { w = 64, h = 64, e = 24, d = 22 },
}

-- Imported interface art replaces these built-in textures when present.
UI.ART_OVERRIDE = { panel = "ui_window", card = "ui_card", inset = "ui_inset", slot = "ui_slot", pill = "ui_pill" }

local function artOverride(id)
	local ui = ns.ART and ns.ART.ui
	local e = id and ui and ui[id]
	if e and e.slice then return e end
end
UI.ArtUI = artOverride

local Slice = {}
Slice.__index = Slice

function Slice:SetColor(r, g, b, a)
	if self.art then r, g, b = 1, 1, 1 end -- painted art keeps its own colours
	for i = 1, 9 do self[i]:SetVertexColor(r, g, b, a or 1) end
end

-- Switch to another texture (imported art entry { file, w, h, slice }).
function Slice:SetArt(e)
	self.art = e
	local ex, ey = e.slice / e.w, e.slice / e.h
	local us = { { 0, ex }, { ex, 1 - ex }, { 1 - ex, 1 } }
	local vs = { { 0, ey }, { ey, 1 - ey }, { 1 - ey, 1 } }
	for r = 1, 3 do
		for c = 1, 3 do
			local t = self[(r - 1) * 3 + c]
			t:SetTexture(UI.MEDIA .. "Art\\" .. e.file)
			t:SetTexCoord(us[c][1], us[c][2], vs[r][1], vs[r][2])
		end
	end
end

function Slice:SetShown(v)
	for i = 1, 9 do
		if v then self[i]:Show() else self[i]:Hide() end
	end
end

-- Covers `frame` (optionally grown by `out` pixels) with a sliced texture.
-- d = displayed edge size; 0 means "half the frame height" (capsules).
-- `on`: the textures belong to that frame instead (drawn with its own
-- pictures, under its children), still covering `frame`.
function UI.Slice(frame, art, layer, d, out, on)
	local a = ART[art]
	local over = artOverride(UI.ART_OVERRIDE[art])
	if over then
		a = { w = over.w, h = over.h, e = over.slice, d = floor(a.d * 1.5) }
	end
	d = d or a.d
	if d == 0 then d = floor(frame:GetHeight() / 2) end
	local w, h = frame:GetWidth(), frame:GetHeight()
	if w > 0 and h > 0 then d = min(d, floor(min(w, h) / 2)) end
	out = out or 0
	local ex, ey = a.e / a.w, a.e / a.h
	local us = { { 0, ex }, { ex, 1 - ex }, { 1 - ex, 1 } }
	local vs = { { 0, ey }, { ey, 1 - ey }, { 1 - ey, 1 } }
	local s = setmetatable({}, Slice)
	s.art = over
	local path = over and (UI.MEDIA .. "Art\\" .. over.file) or UI.Tex(art)
	for r = 1, 3 do
		for c = 1, 3 do
			local t = (on or frame):CreateTexture(nil, layer or "BACKGROUND")
			-- a window's shadow lies under everything on its layer: on the
			-- same layer and sublevel as the window's own panel the game
			-- picks the order, and the shadow (black, 80%) could darken it
			if art == "shadow" then t:SetDrawLayer(layer or "BACKGROUND", -8) end
			t:SetTexture(path)
			t:SetTexCoord(us[c][1], us[c][2], vs[r][1], vs[r][2])
			s[(r - 1) * 3 + c] = t
		end
	end
	local tl, t, tr, l, m, r, bl, b, br = s[1], s[2], s[3], s[4], s[5], s[6], s[7], s[8], s[9]
	for _, x in ipairs({ tl, tr, bl, br }) do x:SetSize(d, d) end
	tl:SetPoint("TOPLEFT", frame, "TOPLEFT", -out, out)
	tr:SetPoint("TOPRIGHT", frame, "TOPRIGHT", out, out)
	bl:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", -out, -out)
	br:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", out, -out)
	t:SetPoint("TOPLEFT", tl, "TOPRIGHT", 0, 0)
	t:SetPoint("BOTTOMRIGHT", tr, "BOTTOMLEFT", 0, 0)
	b:SetPoint("TOPLEFT", bl, "TOPRIGHT", 0, 0)
	b:SetPoint("BOTTOMRIGHT", br, "BOTTOMLEFT", 0, 0)
	l:SetPoint("TOPLEFT", tl, "BOTTOMLEFT", 0, 0)
	l:SetPoint("BOTTOMRIGHT", bl, "TOPRIGHT", 0, 0)
	r:SetPoint("TOPLEFT", tr, "BOTTOMLEFT", 0, 0)
	r:SetPoint("BOTTOMRIGHT", br, "TOPRIGHT", 0, 0)
	m:SetPoint("TOPLEFT", tl, "BOTTOMRIGHT", 0, 0)
	m:SetPoint("BOTTOMRIGHT", br, "TOPLEFT", 0, 0)
	return s
end

------------------------------------------------------------------------
-- Panels
------------------------------------------------------------------------
-- kind: panel (window), card (raised box), inset (sunken box)
function UI.Panel(parent, w, h, kind, shadow)
	local f = CreateFrame("Frame", nil, parent)
	f:SetSize(w, h)
	if shadow then
		f.shadow = UI.Slice(f, "shadow", "BACKGROUND", nil, 12)
	end
	f.bg = UI.Slice(f, kind or "card", "BACKGROUND")
	return f
end

-- A thin horizontal divider.
function UI.Line(parent, w, r, g, b, a)
	local t = parent:CreateTexture(nil, "ARTWORK")
	t:SetSize(w, 1)
	UI.Fill(t, r or 0.35, g or 0.42, b or 0.62, a or 0.5)
	return t
end

------------------------------------------------------------------------
-- Pills and badges
------------------------------------------------------------------------
function UI.Pill(parent, w, h, r, g, b, a)
	local f = CreateFrame("Frame", nil, parent)
	f:SetSize(w, h)
	f.bg = UI.Slice(f, "pill", "BACKGROUND", 0)
	f.bg:SetColor(r or 0, g or 0, b or 0, a or 0.55)
	f.text = UI.Text(f, max(10, min(16, h - 9)))
	f.text:SetPoint("CENTER", f, "CENTER", 0, 0)
	f.text:SetJustifyH("CENTER")
	f.text:SetWordWrap(false)
	function f:SetLabel(t) self.text:SetText(t or "") end
	function f:SetColor(r2, g2, b2, a2) self.bg:SetColor(r2, g2, b2, a2 or 1) end
	return f
end

-- Red notification dot with an optional number.
function UI.Badge(parent, size)
	size = max(14, size or 16)
	local f = CreateFrame("Frame", nil, parent)
	f:SetSize(size, size)
	f.isBadge = true -- sits on its owner's corner on purpose
	f:SetFrameLevel(parent:GetFrameLevel() + 6)
	-- the red dot (its own colours, never tinted); it carries no number
	f.dot = f:CreateTexture(nil, "OVERLAY")
	f.dot:SetTexture(UI.Tex("badge"))
	f.dot:SetAllPoints(f)
	-- on the owner's corner, sticking out only a little so it never reaches
	-- the next button or cell
	f:SetPoint("TOPRIGHT", parent, "TOPRIGHT", 2, 2)
	f:Hide()
	-- v: false/nil/0 hides; true or a count shows the dot
	function f:Set(v)
		self:SetShown(v and v ~= 0 and true or false)
	end
	return f
end

------------------------------------------------------------------------
-- Tooltip (own frame: full control over fonts and layout)
------------------------------------------------------------------------
local tip, cmp -- the tooltip, and the one beside it comparing what is worn
local TIP_WIDTH = 270

local function newTip()
	local t = CreateFrame("Frame", nil, UIParent)
	t:SetFrameStrata("TOOLTIP")
	t:SetClampedToScreen(true)
	t:SetSize(TIP_WIDTH + 20, 40)
	t.bg = UI.Slice(t, "panel", "BACKGROUND", 12)
	if UI.ArtUI("ui_tooltip") then t.bg:SetArt(UI.ArtUI("ui_tooltip")) end
	t.rows = {}
	t:Hide()
	return t
end
local function ensureTip()
	if not tip then tip = newTip() end
	return tip
end

-- lines: array of { left, right, r, g, b } (a line may carry sockets: see
-- UI.Lines in UI/Layout.lua); the line at `title` (1) is the bigger one
local TIP_SOCKET = 16
local function fill(t, lines, title)
	local y = -10
	for i = 1, #lines do
		local l = lines[i]
		local row = t.rows[i]
		if not row then
			row = { left = UI.Text(t, 11), right = UI.Text(t, 11), sockets = {} }
			row.right:SetJustifyH("RIGHT")
			row.left:SetJustifyV("TOP")
			t.rows[i] = row
		end
		local size = (i == (title or 1)) and 13 or 11
		local socks = l.sockets
		local indent = UI.PlaceSockets(row.sockets, t, socks, TIP_SOCKET, 10, y)
		row.left:SetFont(ns.FONT, size, "")
		row.left:SetWidth((l[2] and (TIP_WIDTH - 90) or TIP_WIDTH) - indent)
		row.left:SetText(l[1] or "")
		row.left:SetTextColor(l[3] or 1, l[4] or 1, l[5] or 1)
		row.left:ClearAllPoints()
		row.left:SetPoint("TOPLEFT", t, "TOPLEFT", 10 + indent, y - (socks and 2 or 0))
		row.left:Show()
		if l[2] then
			row.right:SetText(l[2])
			row.right:SetTextColor(l[3] or 1, l[4] or 1, l[5] or 1)
			row.right:ClearAllPoints()
			row.right:SetPoint("TOPRIGHT", t, "TOPRIGHT", -10, y)
			row.right:Show()
		else
			row.right:Hide()
		end
		local h = row.left:GetStringHeight() or size
		if h < size then h = size end
		if socks and h < TIP_SOCKET then h = TIP_SOCKET end
		y = y - h - 3
	end
	for i = #lines + 1, #t.rows do
		t.rows[i].left:Hide()
		t.rows[i].right:Hide()
		UI.PlaceSockets(t.rows[i].sockets, t, nil)
	end
	t:SetSize(TIP_WIDTH + 20, -y + 8)
end

-- compare: lines of a second tooltip shown beside the first (its line 2 the
-- bigger one: line 1 says what it is), at its right, or at the owner's left
-- when the screen has no room on the right
function UI.ShowTip(owner, lines, anchor, compare)
	if not lines or #lines == 0 then return end
	ensureTip()
	fill(tip, lines)
	tip:ClearAllPoints()
	if anchor == "TOP" then
		tip:SetPoint("BOTTOM", owner, "TOP", 0, 6)
	elseif anchor == "LEFT" then
		tip:SetPoint("TOPRIGHT", owner, "TOPLEFT", -6, 0)
	else
		tip:SetPoint("TOPLEFT", owner, "TOPRIGHT", 6, 0)
	end
	tip.owner = owner
	tip:Show()
	if compare and #compare > 0 then
		cmp = cmp or newTip()
		fill(cmp, compare, 2)
		cmp:ClearAllPoints()
		local right, screen = tip:GetRight(), UIParent:GetRight()
		local s1, s2 = tip:GetEffectiveScale() or 1, UIParent:GetEffectiveScale() or 1
		if right and screen and right * s1 + (TIP_WIDTH + 26) * s1 > screen * s2 then
			cmp:SetPoint("TOPRIGHT", owner, "TOPLEFT", -6, 0)
		else
			cmp:SetPoint("TOPLEFT", tip, "TOPRIGHT", 4, 0)
		end
		cmp.owner = owner
		cmp:Show()
	elseif cmp then
		cmp:Hide()
		cmp.owner = nil
	end
end

function UI.HideTip(owner)
	if tip and (owner == nil or tip.owner == owner) then
		tip:Hide()
		tip.owner = nil
	end
	if cmp and (owner == nil or cmp.owner == owner) then
		cmp:Hide()
		cmp.owner = nil
	end
end

-- Attach a tooltip provider: fn(widget) returns the lines to show.
function UI.Tip(widget, fn, anchor)
	widget.tipFn = fn
	widget.tipAnchor = anchor
	widget:SetScript("OnEnter", function(self)
		if self.onEnter then self.onEnter(self) end
		if self.tipFn then
			local lines, compare = self.tipFn(self)
			UI.ShowTip(self, lines, self.tipAnchor, compare)
		end
	end)
	widget:SetScript("OnLeave", function(self)
		if self.onLeave then self.onLeave(self) end
		UI.HideTip(self)
	end)
end

-- the widget whose tooltip is up (nil when none is)
function UI.TipOwner()
	return tip and tip:IsShown() and tip.owner or nil
end

-- what the tooltip shows, line by line ("left  right"; for the checks)
-- the shown tooltip's lines (compare: the one beside it)
function UI.TipText(compare)
	local out = {}
	local t = compare and cmp or tip
	if not (t and t:IsShown()) then return out end
	for _, row in ipairs(t.rows) do
		if row.left:IsShown() then
			out[#out + 1] = (row.left:GetText() or "") .. (row.right:IsShown() and ("  " .. (row.right:GetText() or "")) or "")
		end
	end
	return out
end

function UI.RefreshTip()
	if tip and tip:IsShown() and tip.owner and tip.owner.tipFn then
		local lines, compare = tip.owner.tipFn(tip.owner)
		UI.ShowTip(tip.owner, lines, tip.owner.tipAnchor, compare)
	end
end

function UI.SimpleTip(title, body)
	local lines = { { title, nil, UI.C.gold[1], UI.C.gold[2], UI.C.gold[3] } }
	if body then lines[2] = { body, nil, 1, 1, 1 } end
	return lines
end

------------------------------------------------------------------------
-- Buttons
------------------------------------------------------------------------
-- button style -> imported button art
UI.BUTTON_ART = { primary = "ui_btn_primary", blue = "ui_btn_secondary", dark = "ui_btn_neutral",
	red = "ui_btn_danger", green = "ui_btn_confirm", purple = "ui_btn_secondary" }

local function paint(b)
	local over = artOverride(UI.BUTTON_ART[b.style])
	if over then
		if b.bg.art ~= over then b.bg:SetArt(over) end
		local k = b.off and 0.45 or ((b.hover and 1.12 or 1) * (b.on and 1.15 or 1))
		for i = 1, 9 do
			b.bg[i]:SetVertexColor(min(1, k), min(1, k), min(1, k), 1)
			if b.bg[i].SetDesaturated then b.bg[i]:SetDesaturated(b.off and true or false) end
		end
		b.label:SetTextColor(b.off and 0.6 or 1, b.off and 0.6 or 1, b.off and 0.62 or 1)
		if b.ring then
			if b.on then b.ring:Show() else b.ring:Hide() end
		end
		return
	end
	local c
	if b.off then
		c = UI.STYLE.off
		b.label:SetTextColor(0.50, 0.52, 0.58)
	else
		c = UI.STYLE[b.style] or UI.STYLE.dark
		b.label:SetTextColor(1, 1, 1)
	end
	local k = (b.hover and not b.off) and 1.18 or 1
	if b.on then k = k * 1.25 end
	b.bg:SetColor(min(1, c[1] * k), min(1, c[2] * k), min(1, c[3] * k), 1)
	if b.ring then
		if b.on then b.ring:Show() else b.ring:Hide() end
	end
	if b.arrow then
		if b.off then b.arrow:SetVertexColor(0.45, 0.48, 0.55)
		elseif b.hover then b.arrow:SetVertexColor(0.55, 0.80, 1)
		else b.arrow:SetVertexColor(0.86, 0.89, 0.96) end
	end
	if b.glyph then
		local a = b.off and 0.45 or 1
		b.glyph:SetVertexColor(a, a, a, 1)
	end
end

-- style: primary | blue | green | red | dark | purple
function UI.Button(parent, w, h, text, onClick, style)
	local b = CreateFrame("Button", nil, parent)
	b:SetSize(w, h)
	b.style = style or "dark"
	b.bg = UI.Slice(b, "button", "BACKGROUND")
	b.label = UI.Text(b, h >= 30 and 13 or (h >= 22 and 11 or 10), text)
	b.label:SetPoint("CENTER", b, "CENTER", 0, 0)
	b.label:SetJustifyH("CENTER")
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b.onClick = onClick
	b:SetScript("OnClick", function(self, button)
		if self.off and not self.clickWhenOff then return end
		ns.Sound("click")
		if self.onClick then self.onClick(self, button) end
	end)
	b.onEnter = function(self) self.hover = true paint(self) end
	b.onLeave = function(self) self.hover = false paint(self) end
	b:SetScript("OnEnter", function(self) self.onEnter(self) end)
	b:SetScript("OnLeave", function(self) self.onLeave(self) end)
	function b:SetLabel(t) self.label:SetText(t or "") end
	function b:SetStyle(s) self.style = s paint(self) end
	function b:SetOn(v) self.on = v and true or false paint(self) end
	function b:SetOff(v) self.off = v and true or false paint(self) end
	-- small glyph to the left of the label
	function b:SetGlyph(name)
		if not self.glyph then
			self.glyph = UI.Glyph(self, name, h - 10)
			self.glyph:SetPoint("RIGHT", self.label, "LEFT", -4, 0)
		else
			UI.SetGlyph(self.glyph, name)
		end
		paint(self)
	end
	function b:SetBadge(v)
		if not self.badge then self.badge = UI.Badge(self, 14) end
		self.badge:Set(v)
	end
	paint(b)
	return b
end

-- A page button: the scroll bar sheet's arrow ("left" / "right") instead of
-- a label (the label keeps < or > for whoever reads it).
function UI.PageButton(parent, w, h, dir, onClick)
	local b = UI.Button(parent, w, h, dir == "left" and "<" or ">", onClick, "dark")
	local art = UI.ArtIcon(dir == "left" and "sb_arrow_left" or "sb_arrow_right")
	if art then
		b.label:SetAlpha(0)
		b.arrow = b:CreateTexture(nil, "OVERLAY")
		b.arrow:SetTexture(art)
		local ah = math.floor(h * 0.44 + 0.5)
		b.arrow:SetSize(math.floor(ah / 2 + 0.5), ah)
		b.arrow:SetPoint("CENTER", b, "CENTER", 0, 0)
		b:SetOff(b.off)
	end
	return b
end

-- A round icon button with a caption underneath (menus, docks).
function UI.MenuButton(parent, size, icon, caption, onClick, art)
	local b = CreateFrame("Button", nil, parent)
	b:SetSize(size, size + (caption and 13 or 0))
	b.disc = UI.Art(b, "circle", "BACKGROUND", 0.10, 0.13, 0.22, 1)
	b.disc:SetSize(size, size)
	b.disc:SetPoint("TOP", b, "TOP", 0, 0)
	b.icon = b:CreateTexture(nil, "ARTWORK")
	b.icon:SetSize(size * 0.62, size * 0.62)
	b.icon:SetPoint("CENTER", b.disc, "CENTER", 0, 0)
	UI.SetArtOrIcon(b.icon, art, icon)
	if b.icon.isArt then b.icon:SetVertexColor(0.86, 0.89, 0.96) end
	b.ringT = UI.Art(b, "ring", "OVERLAY", 0.55, 0.62, 0.80)
	b.ringT:SetSize(size, size)
	b.ringT:SetPoint("CENTER", b.disc, "CENTER", 0, 0)
	if caption then
		b.caption = UI.Text(b, 10, caption)
		b.caption:SetPoint("TOP", b.disc, "BOTTOM", 0, -1)
		b.caption:SetJustifyH("CENTER")
		UI.Color(b.caption, UI.C.sub)
	end
	b.badge = UI.Badge(b, 13)
	b.badge:ClearAllPoints()
	b.badge:SetPoint("TOPRIGHT", b.disc, "TOPRIGHT", 2, 2)
	b:RegisterForClicks("LeftButtonUp")
	b:SetScript("OnClick", function(self)
		ns.Sound("click")
		if onClick then onClick(self) end
	end)
	b.onEnter = function(self) self.ringT:SetVertexColor(0.55, 0.80, 1) end
	b.onLeave = function(self) self.ringT:SetVertexColor(0.55, 0.62, 0.80) end
	b:SetScript("OnEnter", function(self) self.onEnter(self) end)
	b:SetScript("OnLeave", function(self) self.onLeave(self) end)
	function b:SetBadge(v) self.badge:Set(v) end
	return b
end

-- Filter / segment chip: a capsule that is either selected or not.
function UI.Chip(parent, w, h, text, onClick)
	local b = CreateFrame("Button", nil, parent)
	b:SetSize(w, h)
	b.bg = UI.Slice(b, "pill", "BACKGROUND", 0)
	b.label = UI.Text(b, h >= 24 and 12 or 11, text)
	b.label:SetPoint("CENTER", b, "CENTER", 0, 0)
	b.label:SetJustifyH("CENTER")
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b:SetScript("OnClick", function(self, button)
		ns.Sound("click")
		if onClick then onClick(self, button) end
	end)
	local function chipPaint(self)
		local art = UI.ArtUI(self.on and "ui_chip_on" or "ui_chip")
		if art then
			if self.bg.art ~= art then self.bg:SetArt(art) end
			local k = (self.hover and not self.on) and 1.12 or 1
			for i = 1, 9 do self.bg[i]:SetVertexColor(min(1, k), min(1, k), min(1, k), 1) end
			self.label:SetTextColor(self.on and 0.12 or 0.88, self.on and 0.10 or 0.90, self.on and 0.05 or 0.96)
			return
		end
		if self.on then
			self.bg:SetColor(0.20, 0.52, 1.00, 1)
			self.label:SetTextColor(1, 1, 1)
			self.label:SetShadowOffset(1, -1)
		else
			-- (dimOff: a list of choices whose unchosen rows sit darker)
			local k = self.dimOff and (self.hover and 0.24 or 0.15) or (self.hover and 0.32 or 0.22)
			self.bg:SetColor(k, k * 1.12, k * 1.5, 1)
			if self.dimOff then self.label:SetTextColor(0.74, 0.77, 0.85) else self.label:SetTextColor(0.85, 0.88, 0.95) end
			self.label:SetShadowOffset(1, -1)
		end
	end
	b.onEnter = function(self) self.hover = true chipPaint(self) end
	b.onLeave = function(self) self.hover = false chipPaint(self) end
	b:SetScript("OnEnter", function(self) self.onEnter(self) end)
	b:SetScript("OnLeave", function(self) self.onLeave(self) end)
	function b:SetOn(v) self.on = v and true or false chipPaint(self) end
	function b:SetLabel(t) self.label:SetText(t or "") end
	function b:SetBadge(v)
		if not self.badge then self.badge = UI.Badge(self, 13) end
		self.badge:Set(v)
	end
	chipPaint(b)
	return b
end

-- A toggle: get() -> bool, set(bool)
function UI.Check(parent, text, get, set)
	local b = CreateFrame("Button", nil, parent)
	b:SetSize(220, 22)
	b.box = UI.Panel(b, 20, 20, "inset")
	b.box:SetPoint("LEFT", b, "LEFT", 0, 0)
	b.mark = UI.Glyph(b.box, "check", 16, UI.C.gold[1], UI.C.gold[2], UI.C.gold[3])
	b.mark:SetPoint("CENTER", b.box, "CENTER", 0, 0)
	b.label = UI.Text(b, 12, text)
	b.label:SetPoint("LEFT", b.box, "RIGHT", 8, 0)
	b.get, b.set = get, set
	function b:Refresh()
		if self.get() then self.mark:Show() else self.mark:Hide() end
	end
	b:RegisterForClicks("LeftButtonUp")
	b:SetScript("OnClick", function(self)
		ns.Sound("click")
		self.set(not self.get())
		self:Refresh()
	end)
	b:SetWidth(30 + b.label:GetStringWidth())
	return b
end

------------------------------------------------------------------------
-- Slot: items, skills, runes, materials ...
------------------------------------------------------------------------
function UI.IconButton(parent, size, onClick)
	local b = CreateFrame("Button", nil, parent)
	b:SetSize(size, size)
	b.isItem = true
	b.slotBg = UI.Art(b, "slot", "BACKGROUND")
	b.slotBg:SetAllPoints(b)
	local pad = max(2, floor(size * 0.07))
	b.icon = b:CreateTexture(nil, "ARTWORK")
	b.icon:SetPoint("TOPLEFT", b, "TOPLEFT", pad, -pad)
	b.icon:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", -pad, pad)
	b.icon:Hide()
	b.shade = b:CreateTexture(nil, "ARTWORK", nil, 2)
	b.shade:SetAllPoints(b.icon)
	UI.Fill(b.shade, 0.02, 0.03, 0.06, 0.70)
	b.shade:Hide()
	b.frame = UI.Art(b, "frame", "OVERLAY")
	b.frame:SetAllPoints(b)
	b.frame:Hide()
	b.hl = UI.Art(b, "frame", "OVERLAY", 0.55, 0.80, 1, 0.9)
	b.hl:SetPoint("TOPLEFT", b, "TOPLEFT", -2, 2)
	b.hl:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", 2, -2)
	b.hl:Hide()
	b.count = UI.Text(b, max(10, floor(size * 0.24)), nil, "OUTLINE")
	b.count:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", -3, 3)
	b.count:SetJustifyH("RIGHT")
	b.mark = UI.Text(b, max(10, floor(size * 0.24)), nil, "OUTLINE")
	b.mark:SetPoint("TOPLEFT", b, "TOPLEFT", 3, -3)
	b.lockG = UI.Glyph(b, "lock", max(10, floor(size * 0.3)), 0.95, 0.75, 0.35)
	b.lockG:SetPoint("TOPRIGHT", b, "TOPRIGHT", -2, -2)
	b.lockG:Hide()
	-- an item's marks (SetItemMarks): its level top left ("lv.20"), the
	-- better-gear arrow top right, its enhancement step bottom right
	b.ilvl = UI.Text(b, max(10, floor(size * 0.22)), nil, "OUTLINE")
	b.ilvl:SetPoint("TOPLEFT", b, "TOPLEFT", 3, -3)
	b.ilvl:SetJustifyH("LEFT")
	-- (a mark on the slot's corner, like the notice dots: it sits on the
	-- corner on purpose, clear of the level text)
	b.upArrow = CreateFrame("Frame", nil, b)
	b.upArrow.isBadge = true
	b.upArrow:SetFrameLevel(b:GetFrameLevel() + 6)
	b.upArrow:SetSize(floor(size * 0.44 + 0.5), floor(size * 0.44 + 0.5))
	b.upArrow:SetPoint("TOPRIGHT", b, "TOPRIGHT", 2, 2)
	b.upArrow.tex = b.upArrow:CreateTexture(nil, "OVERLAY")
	b.upArrow.tex:SetTexture(UI.ArtPath("icon_upgrade"))
	b.upArrow.tex:SetAllPoints(b.upArrow)
	b.upArrow:Hide()
	-- the enhancement step, "+10": larger than the level, low in the
	-- corner (a mark on the corner like the notice dots, over the border)
	local fs = max(12, floor(size * 0.3))
	b.enhF = CreateFrame("Frame", nil, b)
	b.enhF.isBadge = true
	b.enhF:SetFrameLevel(b:GetFrameLevel() + 5)
	b.enhF:SetSize(floor(size * 0.7), fs + 2)
	b.enhF:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", -3, -1)
	b.enh = UI.Text(b.enhF, fs, nil, "OUTLINE")
	b.enh:SetPoint("BOTTOMRIGHT", b.enhF, "BOTTOMRIGHT", 0, 0)
	b.enh:SetJustifyH("RIGHT")
	b.enhF:Hide()
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b.onClick = onClick
	b:SetScript("OnClick", function(self, button)
		if self.onClick then self.onClick(self, button) end
	end)
	b.onEnter = function(self) self.hover = true self.hl:Show() end
	b.onLeave = function(self) self.hover = false if not self.selected then self.hl:Hide() end end
	b:SetScript("OnEnter", function(self) self.onEnter(self) end)
	b:SetScript("OnLeave", function(self) self.onLeave(self) end)

	function b:SetIconName(name)
		if name then
			UI.SetIcon(self.icon, name)
			self.icon:Show()
		else
			self.icon:Hide()
		end
	end
	-- an imported icon if there is one, else a game icon
	function b:SetArtIcon(artId, iconName)
		UI.SetArtOrIcon(self.icon, artId, iconName)
		self.icon:Show()
	end
	-- the quality colours both the frame and, softly, the card behind the icon
	function b:SetQuality(q)
		local card = q and UI.ArtPath("item_q" .. q)
		if card then
			-- a painted background per rarity (it has its own border)
			self.slotBg:SetTexture(card)
			self.slotBg:SetTexCoord(0, 1, 0, 1)
			self.slotBg:SetVertexColor(1, 1, 1)
			self.frame:Hide()
			self.qArt = true
			return
		end
		if self.qArt then UI.SetGlyph(self.slotBg, "slot") self.qArt = nil end
		if q and ns.QUALITY[q] then
			local r, g, bl = ns.U.rgb(ns.QUALITY[q].hex)
			-- a grade of several colours has its frame painted in them
			local painted = ns.QUALITY[q].frame
			if painted ~= self.frameTex then
				self.frame:SetTexture(UI.Tex(painted or "frame"))
				self.frameTex = painted
			end
			if painted then self.frame:SetVertexColor(1, 1, 1) else self.frame:SetVertexColor(r, g, bl) end
			self.frame:Show()
			self.slotBg:SetVertexColor(0.35 + r * 0.5, 0.35 + g * 0.5, 0.35 + bl * 0.5)
		else
			self.frame:Hide()
			self.slotBg:SetVertexColor(1, 1, 1)
		end
	end
	function b:SetBorderRGB(r, g, bl)
		if self.frameTex then
			self.frame:SetTexture(UI.Tex("frame"))
			self.frameTex = nil
		end
		self.frame:SetVertexColor(r, g, bl, 1)
		self.frame:Show()
	end
	function b:SetCount(t) self.count:SetText(t or "") end
	-- an item in the slot: its level, its enhancement step ("+10") and,
	-- given better = true, the better-gear arrow; a protected item's lock
	-- moves to the bottom left, clear of the arrow
	function b:SetItemMarks(it, better)
		self.ilvl:SetText(it and it.l and ("lv." .. it.l) or "")
		local n = it and it.up or 0
		self.enh:SetText(n > 0 and ("+" .. n) or "")
		self.enhF:SetShown(n > 0)
		self.upArrow:SetShown(better and true or false)
		self.lockG:ClearAllPoints()
		self.lockG:SetPoint("BOTTOMLEFT", self, "BOTTOMLEFT", 2, 2)
		local l = max(10, floor(self:GetWidth() * 0.24))
		self.lockG:SetSize(l, l)
	end
	function b:SetMark(t, r, g, bl)
		self.mark:SetText(t or "")
		if r then self.mark:SetTextColor(r, g, bl) end
	end
	function b:SetDim(v) if v then self.shade:Show() else self.shade:Hide() end end
	function b:SetLocked(v) if v then self.lockG:Show() else self.lockG:Hide() end end
	function b:SetSelected(v)
		self.selected = v and true or false
		if self.selected or self.hover then self.hl:Show() else self.hl:Hide() end
	end
	function b:SetBadge(v)
		if not self.badge then self.badge = UI.Badge(self, 13) end
		self.badge:Set(v)
	end
	function b:Clear()
		self.icon:Hide()
		self:SetQuality(nil)
		self:SetCount(nil)
		self:SetMark(nil)
		self.ilvl:SetText("")
		self.enh:SetText("")
		self.enhF:Hide()
		self.upArrow:Hide()
		self.lockG:ClearAllPoints()
		self.lockG:SetPoint("TOPRIGHT", self, "TOPRIGHT", -2, -2)
		local l = max(10, floor(self:GetWidth() * 0.3))
		self.lockG:SetSize(l, l)
		self:SetDim(false)
		self:SetLocked(false)
		self:SetSelected(false)
		if self.badge then self.badge:Set(false) end
		self.data = nil
	end
	return b
end

------------------------------------------------------------------------
-- Round hero portrait: class circle, role-colored ring, level pill.
------------------------------------------------------------------------
function UI.Portrait(parent, size, onClick)
	local b = CreateFrame("Button", nil, parent)
	b:SetSize(size, size)
	b.isItem = true
	b.disc = UI.Art(b, "circle", "BACKGROUND", 0.06, 0.08, 0.14)
	b.disc:SetAllPoints(b)
	b.icon = b:CreateTexture(nil, "ARTWORK")
	local pad = floor(size * 0.09)
	b.icon:SetPoint("TOPLEFT", b, "TOPLEFT", pad, -pad)
	b.icon:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", -pad, pad)
	b.ringT = UI.Art(b, "ring", "OVERLAY")
	b.ringT:SetAllPoints(b)
	b.hl = UI.Art(b, "glow", "BACKGROUND", 0.35, 0.62, 1, 0.8)
	b.hl:SetPoint("TOPLEFT", b, "TOPLEFT", -size * 0.22, size * 0.22)
	b.hl:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", size * 0.22, -size * 0.22)
	b.hl:Hide()
	b.lvl = UI.Pill(b, max(22, floor(size * 0.55)), max(13, floor(size * 0.28)), 0.05, 0.06, 0.10, 0.92)
	b.lvl:SetPoint("BOTTOM", b, "BOTTOM", 0, -floor(size * 0.10))
	b.lvl:SetFrameLevel(b:GetFrameLevel() + 3)
	-- (no role mark on the portrait; kept hidden for callers that touch it)
	b.role = UI.Glyph(b, "role_tank", max(10, floor(size * 0.30)))
	b.role:Hide()
	b.role:SetPoint("TOPLEFT", b, "TOPLEFT", -2, 2)
	b.badge = UI.Badge(b, max(12, floor(size * 0.28)))
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b:SetScript("OnClick", function(self, button)
		ns.Sound("click")
		if onClick then onClick(self, button) end
	end)
	b.onEnter = function(self) self.hover = true self.hl:Show() end
	b.onLeave = function(self) self.hover = false if not self.selected then self.hl:Hide() end end
	b:SetScript("OnEnter", function(self) self.onEnter(self) end)
	b:SetScript("OnLeave", function(self) self.onLeave(self) end)

	-- heroId or nil (empty)
	function b:SetHero(id)
		self.heroId = id
		local h = id and ns.db.heroes[id]
		if not h then
			self.icon:Hide()
			self.lvl:Hide()
			self.role:Hide()
			self.ringT:SetVertexColor(0.30, 0.34, 0.45)
			return
		end
		local sp = ns.SPECS[h.spec]
		UI.SetClassIcon(self.icon, sp.class)
		self.icon:Show()
		local r, g, bl = ns.U.rgb(ns.ROLE[sp.role].hex)
		self.ringT:SetVertexColor(r, g, bl)
		self.role:Hide()
		self.lvl:SetLabel(tostring(h.level))
		self.lvl:Show()
	end
	function b:SetSelected(v)
		self.selected = v and true or false
		if self.selected or self.hover then self.hl:Show() else self.hl:Hide() end
	end
	function b:SetDim(v)
		self.icon:SetDesaturated(v and true or false)
		self.icon:SetAlpha(v and 0.5 or 1)
	end
	function b:SetBadge(v) self.badge:Set(v) end
	return b
end

------------------------------------------------------------------------
-- Progress bar
------------------------------------------------------------------------
function UI.Bar(parent, w, h, r, g, b)
	local f = CreateFrame("Frame", nil, parent)
	f:SetSize(w, h)
	f.bg = f:CreateTexture(nil, "BACKGROUND")
	f.bg:SetAllPoints(f)
	UI.Fill(f.bg, 0.02, 0.03, 0.05, 0.85)
	f.fill = UI.Art(f, "bar", "ARTWORK", r or 0.2, g or 0.8, b or 0.2)
	f.fill:SetPoint("TOPLEFT", f, "TOPLEFT", 1, -1)
	f.fill:SetPoint("BOTTOMLEFT", f, "BOTTOMLEFT", 1, 1)
	f.inner = w - 2
	if UI.ArtUI("ui_bar_frame") then
		f.frameArt = UI.Slice(f, "pill", "OVERLAY", min(h, 12), 2)
		f.frameArt:SetArt(UI.ArtUI("ui_bar_frame"))
	end
	f.text = UI.Text(f, max(10, min(11, h - 3)), nil, "OUTLINE")
	f.text:SetPoint("CENTER", f, "CENTER", 0, 0)
	f.text:SetJustifyH("CENTER")
	function f:SetValue(v)
		if v ~= v then v = 0 end -- NaN guard
		v = ns.U.clamp(v or 0, 0, 1)
		if v <= 0 then
			self.fill:Hide()
		else
			self.fill:Show()
			self.fill:SetWidth(max(1, self.inner * v))
		end
	end
	function f:SetRGB(r2, g2, b2) self.fill:SetVertexColor(r2, g2, b2, 1) end
	function f:SetLabel(t) self.text:SetText(t or "") end
	function f:SetBarWidth(w2)
		self:SetWidth(w2)
		self.inner = w2 - 2
	end
	f:SetValue(0)
	return f
end

------------------------------------------------------------------------
-- Misc helpers
------------------------------------------------------------------------
function UI.Gold(n)
	return "|cffffd24a" .. ns.U.fmt(n) .. "|r G"
end

-- Turns a (ok, reason) result into a toast when it failed.
function UI.Try(ok, why)
	if not ok and why then
		ns.Fire("TOAST", "|cffff6a5a" .. why .. "|r")
	end
	return ok
end

